import{c as d,Q as r,j as e,m as o}from"./chunks/framework.rWdQudnF.js";const b=JSON.parse('{"title":"架构师-备考 案例分析-Redis缓存技术","description":"","frontmatter":{"title":"架构师-备考 案例分析-Redis缓存技术"},"headers":[],"relativePath":"案例分析/Redis缓存技术.md","filePath":"案例分析/Redis缓存技术.md","lastUpdated":null}'),a={name:"案例分析/Redis缓存技术.md"};function s(l,t,n,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] Redis 5 种基本类型 + 3 种特殊类型</li><li>[x] 缓存穿透/雪崩/击穿（现象 + 解决方案）</li><li>[x] Redis 3 种过期策略（定时/惰性/定期）</li><li>[x] Redis 8 种内存淘汰策略</li><li>[x] RDB vs AOF 持久化机制对比</li><li>[x] Redis 3 种高可用架构（主从/哨兵/Cluster）</li><li>[x] Redis 分布式锁（SETNX → 看门狗 → Redlock）</li><li>[x] Cache-Aside 模式读写流程 + 双写一致性</li><li>[x] MySQL 分布式锁缺点</li><li>[x] 基于 ZSet 的分布式锁命令</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、redis-基础类型" tabindex="-1">一、Redis 基础类型 <a class="header-anchor" href="#一、redis-基础类型" aria-label="Permalink to &quot;一、Redis 基础类型&quot;">​</a></h3><p><strong>五种基本类型：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td><strong>String</strong></td><td>最基本字符串类型</td></tr><tr><td><strong>Hash</strong></td><td>key-value 结构（field-value 对），适合对象存储</td></tr><tr><td><strong>List</strong></td><td>有序可重复列表</td></tr><tr><td><strong>Set</strong></td><td>无序不可重复集合</td></tr><tr><td><strong>ZSet</strong></td><td>有序集合（带排序），<strong>考试重点</strong>（如排行榜），改版后考过相关命令</td></tr></tbody></table><p><strong>三种特殊类型：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>用途</th></tr></thead><tbody><tr><td><strong>Geo</strong></td><td>Redis 3.2+，存储地理位置信息</td></tr><tr><td><strong>HyperLogLog</strong></td><td>基数统计（如网站 UV 统计）</td></tr><tr><td><strong>Bitmaps</strong></td><td>位图，单比特映射元素状态（类似操作系统位示图）</td></tr></tbody></table><hr><h3 id="二、缓存问题分析-★" tabindex="-1">二、缓存问题分析 ★ <a class="header-anchor" href="#二、缓存问题分析-★" aria-label="Permalink to &quot;二、缓存问题分析 ★&quot;">​</a></h3><h4 id="_1-缓存穿透" tabindex="-1">1. 缓存穿透 <a class="header-anchor" href="#_1-缓存穿透" aria-label="Permalink to &quot;1. 缓存穿透&quot;">​</a></h4><blockquote><p>查询不存在的数据时，缓存和数据库均无记录，导致每次请求直达数据库。</p></blockquote><p><strong>解决方案：</strong></p><table tabindex="0"><thead><tr><th>方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>参数校验</strong></td><td>API 入口过滤非法值</td></tr><tr><td><strong>空值缓存</strong></td><td>对空结果也缓存，设合理过期时间（需维护一致性）</td></tr><tr><td><strong>布隆过滤器</strong></td><td>2022 考点，概率型数据结构快速判断存在性，空间效率极高</td></tr></tbody></table><h4 id="_2-缓存雪崩" tabindex="-1">2. 缓存雪崩 <a class="header-anchor" href="#_2-缓存雪崩" aria-label="Permalink to &quot;2. 缓存雪崩&quot;">​</a></h4><blockquote><p>大规模缓存失效引发数据库崩溃。场景：大量缓存同时过期 / Redis 集群整体故障。</p></blockquote><table tabindex="0"><thead><tr><th>解决方案</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>过期时间随机化</td><td>实现简单</td><td>不能应对 Redis 宕机</td></tr><tr><td>缓存预热</td><td>热点数据命中率高</td><td>需维护热点列表</td></tr><tr><td>多级缓存</td><td>高性能、降低 Redis 依赖</td><td>本地缓存一致性问题</td></tr><tr><td>Redis 高可用</td><td>避免单点故障</td><td>成本高、架构复杂</td></tr><tr><td>限流 &amp; 降级</td><td>保护数据库</td><td>用户体验可能受影响</td></tr><tr><td>热点数据永不过期</td><td>命中率极高</td><td>数据可能过期不一致</td></tr></tbody></table><blockquote><p>生产环境：过期时间随机化 + Redis 集群高可用 + 多级缓存 + 限流降级组合使用。</p></blockquote><h4 id="_3-缓存击穿" tabindex="-1">3. 缓存击穿 <a class="header-anchor" href="#_3-缓存击穿" aria-label="Permalink to &quot;3. 缓存击穿&quot;">​</a></h4><blockquote><p>单点热点 key 失效（vs 雪崩的大面积失效）。如秒杀商品、爆款新闻过期并发查询。</p></blockquote><table tabindex="0"><thead><tr><th>解决方案</th><th>说明</th></tr></thead><tbody><tr><td><strong>互斥锁</strong></td><td>2024 考点，原子操作控制并发重建缓存</td></tr><tr><td><strong>逻辑永不过期</strong></td><td>设较长 TTL，异步线程监控热点 key 临近过期自动续期</td></tr><tr><td><strong>集群分流</strong></td><td>Redis 集群分散读流量</td></tr><tr><td><strong>多级缓存</strong></td><td>本地缓存 + 分布式缓存多层结构</td></tr></tbody></table><hr><h3 id="三、redis-过期策略" tabindex="-1">三、Redis 过期策略 <a class="header-anchor" href="#三、redis-过期策略" aria-label="Permalink to &quot;三、Redis 过期策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>机制</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>定时过期</strong></td><td>每个 key 创建独立定时器，到期立即清除</td><td>内存友好</td><td>消耗大量 CPU</td></tr><tr><td><strong>惰性过期</strong></td><td>仅在访问 key 时判断是否过期</td><td>节省 CPU</td><td>过期 key 可能堆积</td></tr><tr><td><strong>定期过期</strong></td><td>每隔 ~100ms 随机抽取部分 key 检查</td><td>平衡 CPU 和内存</td><td>清理不够及时</td></tr></tbody></table><blockquote><p>生产环境默认：惰性过期 + 定期过期结合。</p></blockquote><hr><h3 id="四、redis-8-种内存淘汰策略-★" tabindex="-1">四、Redis 8 种内存淘汰策略 ★ <a class="header-anchor" href="#四、redis-8-种内存淘汰策略-★" aria-label="Permalink to &quot;四、Redis 8 种内存淘汰策略 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>范围</th><th>算法</th><th>核心机制</th></tr></thead><tbody><tr><td><strong>volatile-lru</strong></td><td>过期 key</td><td>LRU</td><td>淘汰最近最少使用</td></tr><tr><td><strong>allkeys-lru</strong></td><td>所有 key</td><td>LRU</td><td>全局淘汰冷数据</td></tr><tr><td><strong>volatile-lfu</strong></td><td>过期 key</td><td>LFU</td><td>淘汰最不常用（Redis 4.0+）</td></tr><tr><td><strong>allkeys-lfu</strong></td><td>所有 key</td><td>LFU</td><td>全局频率淘汰</td></tr><tr><td><strong>volatile-random</strong></td><td>过期 key</td><td>随机</td><td>随机淘汰</td></tr><tr><td><strong>allkeys-random</strong></td><td>所有 key</td><td>随机</td><td>全局随机</td></tr><tr><td><strong>volatile-ttl</strong></td><td>过期 key</td><td>TTL</td><td>淘汰即将过期 key</td></tr><tr><td><strong>noeviction</strong></td><td>全局</td><td>无淘汰</td><td>内存满拒写报错（<strong>默认</strong>）</td></tr></tbody></table><blockquote><p>生产环境优先 <code>allkeys-lru</code> 或 <code>allkeys-lfu</code>。</p></blockquote><hr><h3 id="五、持久化机制-rdb-vs-aof-★" tabindex="-1">五、持久化机制 RDB vs AOF ★ <a class="header-anchor" href="#五、持久化机制-rdb-vs-aof-★" aria-label="Permalink to &quot;五、持久化机制 RDB vs AOF ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比</th><th>RDB（快照）</th><th>AOF（追加日志）</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>定时生成内存快照 → <code>dump.rdb</code></td><td>记录每个写命令到 <code>appendonly.aof</code></td></tr><tr><td><strong>触发</strong></td><td>手动 <code>save</code>/<code>bgsave</code>，自动按时间 + 写次数</td><td><code>always</code>/<code>everysec</code>/<code>no</code></td></tr><tr><td><strong>优点</strong></td><td>文件小、恢复快、适合大规模备份</td><td>数据安全性高、准实时持久化</td></tr><tr><td><strong>缺点</strong></td><td>两次快照间可能丢数据</td><td>文件大、恢复慢</td></tr><tr><td><strong>类比</strong></td><td><strong>全量备份</strong></td><td><strong>操作日志</strong></td></tr></tbody></table><blockquote><p>生产：RDB + AOF 混合持久化（Redis 4.0+）。</p></blockquote><hr><h3 id="六、高可用架构" tabindex="-1">六、高可用架构 <a class="header-anchor" href="#六、高可用架构" aria-label="Permalink to &quot;六、高可用架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>核心机制</th><th>优势</th><th>缺陷</th></tr></thead><tbody><tr><td><strong>主从模式</strong></td><td>Master 写 + Slave 读，读写分离，全量+增量复制，<code>repl_backlog</code> 断线续传</td><td>架构简单</td><td>主节点故障需人工切换</td></tr><tr><td><strong>哨兵模式</strong></td><td>多 Sentinel 心跳检测（PING），主观/客观下线，自动 failover（Redis 2.8+）</td><td>自动故障检测与切换</td><td>部署复杂，全量副本</td></tr><tr><td><strong>Cluster 集群</strong></td><td>16384 Hash Slot（CRC16+取模），Gossip 协议通信，302 重定向</td><td>可水平扩容，分布式存储</td><td>配置维护复杂</td></tr></tbody></table><blockquote><p>演进：主从 → 哨兵（自动故障转移）→ Cluster（分布式+在线扩容）。</p><ul><li>小规模：主从 + 哨兵</li><li>中大规模：Redis Cluster</li></ul></blockquote><hr><h3 id="七、分布式锁演进-★" tabindex="-1">七、分布式锁演进 ★ <a class="header-anchor" href="#七、分布式锁演进-★" aria-label="Permalink to &quot;七、分布式锁演进 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>核心</th><th>缺陷</th></tr></thead><tbody><tr><td><strong>SETNX + 过期时间</strong></td><td><code>SETNX key value</code> 加锁，<code>DEL key</code> 解锁</td><td>单节点故障锁丢失；长事务过期失效</td></tr><tr><td><strong>看门狗续期</strong>（Redisson）</td><td>后台线程定期续期，默认每 10s</td><td>仍依赖单节点</td></tr><tr><td><strong>Redlock 算法</strong></td><td>多独立 Redis Master（通常 5 个），超半数加锁成功 + 耗时 &lt; TTL</td><td>实现复杂，网络延迟影响</td></tr></tbody></table><blockquote><p>演进：SETNX → 看门狗 → Redlock（多节点多数派原则）。</p></blockquote><hr><h3 id="八、基于-zset-的分布式锁命令-★" tabindex="-1">八、基于 ZSet 的分布式锁命令 ★ <a class="header-anchor" href="#八、基于-zset-的分布式锁命令-★" aria-label="Permalink to &quot;八、基于 ZSet 的分布式锁命令 ★&quot;">​</a></h3><p>背记：<strong>ZADD 抢锁，ZREM 放锁，ZREMRANGEBYSCORE 清过期</strong></p><table tabindex="0"><thead><tr><th>操作</th><th>命令</th></tr></thead><tbody><tr><td>获取锁</td><td><code>ZADD lock_zset &lt;score&gt; &lt;lock_id&gt;</code></td></tr><tr><td>释放锁</td><td><code>ZREM lock_zset &lt;lock_id&gt;</code></td></tr><tr><td>清理过期锁</td><td><code>ZREMRANGEBYSCORE lock_zset -inf &lt;current_timestamp&gt;</code></td></tr><tr><td>检查锁存在</td><td><code>ZSCORE lock_zset &lt;lock_id&gt;</code></td></tr></tbody></table><hr><h3 id="九、mysql-分布式锁缺点" tabindex="-1">九、MySQL 分布式锁缺点 <a class="header-anchor" href="#九、mysql-分布式锁缺点" aria-label="Permalink to &quot;九、MySQL 分布式锁缺点&quot;">​</a></h3><ol><li><strong>性能瓶颈</strong>：每次锁操作需执行 SQL</li><li><strong>单点故障</strong>：MySQL 宕机锁全部失效</li><li><strong>死锁处理复杂</strong>：需额外死锁检测和超时机制</li><li><strong>实现复杂度高</strong>：需手动编写 SQL + 事务</li><li><strong>可扩展性差</strong>：难以应对大规模分布式系统</li><li><strong>锁粒度控制困难</strong>：基于行/表，粒度较粗</li></ol><hr><h3 id="十、cache-aside-模式" tabindex="-1">十、Cache-Aside 模式 <a class="header-anchor" href="#十、cache-aside-模式" aria-label="Permalink to &quot;十、Cache-Aside 模式&quot;">​</a></h3><p><strong>读流程</strong>：请求缓存 → 命中返回 → 未命中查 DB → 更新缓存 → 返回数据。</p><p><strong>写流程</strong>：更新数据库 → 删除/失效缓存（使后续读取获取最新数据）。</p><p><strong>双写一致性解决方案：</strong></p><ol><li>分布式锁（Redis SETNX）：写前加锁，读写串行化</li><li>延迟双删：写库后删一次，延迟 500ms 再删一次</li><li>异步消息队列（Canal + Kafka）：监听 binlog 异步失效缓存</li><li>版本号/逻辑时钟：缓存带版本，读时比对 DB 版本</li></ol><hr><h3 id="十一、redis-主从复制流程" tabindex="-1">十一、Redis 主从复制流程 <a class="header-anchor" href="#十一、redis-主从复制流程" aria-label="Permalink to &quot;十一、Redis 主从复制流程&quot;">​</a></h3><p><strong>全量同步（首次）</strong>：从库发 <code>PSYNC ? -1</code> → 主库返回 <code>FULLRESYNC replid offset</code> → 主库 <code>bgsave</code> 生成 RDB → 发送 RDB → 从库清空本地加载 RDB → 主库发送 <code>repl_backlog</code> 中命令。</p><p><strong>增量同步（断线重连）</strong>：从库发 <code>PSYNC replid offset</code> → 主库判断 replid 一致 → 回复 <code>CONTINUE</code> → 从 <code>repl_backlog</code> 读取 offset 之后的命令发送。</p>',58)])])}const u=d(a,[["render",s]]);export{b as __pageData,u as default};
